INSERT INTO games(id,slug,name,status,description,rules,version,config,cover_asset_id,banner_asset_id,category_id,sort,featured,hot,program_path) VALUES('golden-god','golden-god','黄金财神','published','黄金财神 · 独立原创转轴玩法，仅虚拟积分体验。','原创演示规则：3×3五条完整连线；财神7为Wild；图标倍率2/3/4/5/7/10/15/20，逐线累加。','0.2.0','{"id": "golden-god", "name": "黄金财神", "columns": 3, "rows": 3, "symbols": ["金", "玉", "福", "禄", "寿", "宝", "財", "神"], "color": "#c99a38", "rules": "原创演示规则：3×3五条完整连线；财神7为Wild；图标倍率2/3/4/5/7/10/15/20，逐线累加。", "motif": "sigil", "speed": 65, "audio": {"melody": [146.83, 174.61, 220.0, 293.66, 220.0, 174.61], "wave": "sine", "interval": 850}, "version": "0.2.0", "original": true, "pendingOriginalRules": true}','webp-cover-golden-god-809c6b0dee','webp-banner-golden-god-8a29d18980','slots','0','1','1','/games/golden-god');
INSERT INTO game_integrations(id,game_id,version,status,program_path,rules,pending_rules) VALUES('golden-god-v02','golden-god','0.2.0','published','/games/golden-god','原创演示规则：3×3五条完整连线；财神7为Wild；图标倍率2/3/4/5/7/10/15/20，逐线累加。','授权原版参数仍待确认；本版本为原创规则');
INSERT INTO games(id,slug,name,status,description,rules,version,config,cover_asset_id,banner_asset_id,category_id,sort,featured,hot,program_path) VALUES('dragon-world','dragon-world','龙腾四海','published','龙腾四海 · 独立原创转轴玩法，仅虚拟积分体验。','原创演示规则：5×3从左连续三列起算243路；Wild8代替普通图标0–7，每个普通图标单独评估；奖励=向下取整(积分×路数×图标倍率×(连续列数−2)/3)；图标倍率1/2/3/4/5/6/8/10；Scatter9至少三枚使本局奖励翻倍。','0.2.0','{"id": "dragon-world", "name": "龙腾四海", "columns": 5, "rows": 3, "symbols": ["青", "赤", "白", "玄", "玉", "珠", "金", "龍", "星", "印"], "color": "#3197a1", "rules": "原创演示规则：5×3从左连续三列起算243路；Wild8代替普通图标0–7，每个普通图标单独评估；奖励=向下取整(积分×路数×图标倍率×(连续列数−2)/3)；图标倍率1/2/3/4/5/6/8/10；Scatter9至少三枚使本局奖励翻倍。", "motif": "orbit", "speed": 77, "audio": {"melody": [155.56, 195.99, 233.08, 311.12, 233.08, 184.99], "wave": "triangle", "interval": 970}, "version": "0.2.0", "original": true, "pendingOriginalRules": true}','webp-cover-dragon-world-607e61e9c6','webp-banner-dragon-world-2bb7c5d05a','slots','1','1','1','/games/dragon-world');
